<?php
$pageTitle = "ID Cards & Chest Numbers";

define("EVENT_AUTHORITY_SCOPE", "members-info");
require_once __DIR__ . "/../../includes/admin-helpers.php";
require_login();

$pdo = $GLOBALS["musabaqa_pdo"];
$activeEvent = admin_require_active_event($pdo);
$activeEventId = (int)$activeEvent["id"];

$stmt = $pdo->prepare("
    SELECT 
        mtm.id AS member_id,
        mtm.student_id,
        mtm.chest_number,
        t.team_name,
        t.team_color,
        ev.title AS event_title,
        COALESCE(NULLIF(s.display_name, ''), s.full_name) AS display_name,
        s.full_name,
        s.name_arabic,
        s.place,
        s.admission_no,
        c.name AS class_name,
        ct.name AS class_type_name,
        u.username,
        u.phone AS user_phone,
        u.email AS user_email,
        m.name AS maddhab_name,
        m.name_arabic AS maddhab_name_arabic
    FROM musabaqa_team_members mtm
    JOIN musabaqa_teams t ON t.id = mtm.team_id
    JOIN musabaqa_events ev ON ev.id = mtm.event_id
    JOIN kauzariyya.students s ON s.id = mtm.student_id
    LEFT JOIN kauzariyya.users u ON u.id = s.user_id
    LEFT JOIN kauzariyya.classes c ON c.id = s.class_id
    LEFT JOIN kauzariyya.class_types ct ON ct.id = c.class_type_id
    LEFT JOIN kauzariyya.maddhabs m ON m.id = s.maddhab_id
    WHERE mtm.event_id = ?
      AND mtm.status = 'active'
    ORDER BY NULLIF(mtm.chest_number, '') IS NULL ASC, 
             CAST(mtm.chest_number AS UNSIGNED) ASC, 
             t.team_name ASC, 
             display_name ASC
");
$stmt->execute([$activeEventId]);
$members = $stmt->fetchAll(PDO::FETCH_ASSOC);

