    box-shadow: 0 4px 15px rgba(0,0,0,0.2);
    position: relative;
    overflow: hidden;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    min-height: 200px;
    color: #fff;
}

.id-card-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    border-bottom: 1px solid rgba(255,255,255,0.1);
    padding-bottom: 10px;
    margin-bottom: 12px;
}

.id-card-event {
    font-size: 11px;
    text-transform: uppercase;
    font-weight: bold;
    color: var(--muted-2);
}

.id-card-chest {
