    font-weight: 900;
    color: #34d399;
    background: rgba(52, 211, 153, 0.1);
    padding: 2px 8px;
    border-radius: 6px;
    line-height: 1;
}

.id-card-body {
    flex-grow: 1;
    margin-bottom: 12px;
}

.id-card-name {
    font-size: 18px;
    font-weight: bold;
    margin-bottom: 4px;
}

.id-card-name-arabic {
    font-size: 16px;
    font-family: "Amiri", serif;
